//! Genuine initial child Range construction and metadata preserve native authority.
use super::*;
fn fixture()->(Document,Forms,Page){
 let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root>Main</div><input id=neighbor value=seed></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://child-range.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var root=document.getElementById('root'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,cd=w.document,html=cd.documentElement,head=cd.head,body=cd.body,mainFactory=Document.prototype.createRange,childFactory=w.Document.prototype.createRange,mainCtor=Range,childCtor=w.Range;");(d,f,p)
}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn range_child_constructors_factories_native_realm_and_receiver_document_are_independent(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var a=new w.Range(),b=cd.createRange(),c=mainFactory.call(cd),d=childFactory.call(document);if(a===b||!(a instanceof childCtor)||a instanceof mainCtor||Object.getPrototypeOf(a)!==childCtor.prototype||a.startContainer!==cd||a.endContainer!==cd||a.startOffset||a.endOffset||!a.collapsed||!(b instanceof childCtor)||b.startContainer!==cd||!(c instanceof mainCtor)||c instanceof childCtor||c.startContainer!==cd||!(d instanceof childCtor)||d instanceof mainCtor||d.startContainer!==document)throw 'callee canonical Range realm independent of Document receiver';
var native=childCtor.prototype;w.Function('Range=function(){};Document=function(){};')();var again=childFactory.call(cd);if(Object.getPrototypeOf(again)!==native||again.startContainer!==cd||again.commonAncestorContainer!==cd)throw 'saved factory keeps canonical native realm after binding shadow';
var caught=0;for(var fake of [{},document.body,new StaticRange({startContainer:root,startOffset:0,endContainer:root,endOffset:0})]){try{childFactory.call(fake);}catch(e){if(e instanceof w.TypeError)caught++;}}if(caught!==3)throw 'real Document factory brand and method realm';
"#);}
#[test]
fn range_child_boundaries_relative_order_queries_clone_empty_text_and_root_switches(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var r=new childCtor();r.selectNodeContents(html);if(r.startContainer!==html||r.startOffset||r.endContainer!==html||r.endOffset!==2||r.commonAncestorContainer!==html||r.collapsed||r.toString()!==''||r.comparePoint(head,0)!==0||r.comparePoint(body,0)!==0||!r.intersectsNode(head)||!r.intersectsNode(body))throw 'native child physical topology and actual empty text';
var copied=r.cloneRange();r.setStartAfter(head);r.setEndBefore(body);if(!r.collapsed||r.startContainer!==html||r.startOffset!==1||copied.startOffset!==0||copied.endOffset!==2||r.compareBoundaryPoints(Range.START_TO_START,copied)!==1)throw 'relative ordering and independent clone';r.selectNode(body);if(r.startContainer!==html||r.startOffset!==1||r.endOffset!==2)throw 'select actual child Node';r.collapse(false);if(!r.collapsed||r.startOffset!==2||r.endOffset!==2)throw 'child endpoint collapse';
var failed=false;try{r.setStart(body,1);}catch(e){failed=e instanceof w.DOMException&&e.name==='IndexSizeError';}if(!failed||r.startOffset!==2)throw 'actual child Node length';failed=false;try{r.setStartBefore(cd);}catch(e){failed=e.name==='InvalidNodeTypeError';}if(!failed)throw 'Document has no relative parent';
r.setStart(root.firstChild,2);if(r.startContainer!==root.firstChild||r.endContainer!==root.firstChild||!r.collapsed||!(r instanceof childCtor))throw 'switch root keeps Range method realm';r.setEnd(head,0);if(r.startContainer!==head||r.endContainer!==head||!r.collapsed||r.commonAncestorContainer!==head||r.toString()!=='')throw 'switch back to actual child root';var outside=new mainCtor();outside.selectNodeContents(root);failed=false;try{r.compareBoundaryPoints(0,outside);}catch(e){failed=e.name==='WrongDocumentError';}if(!failed||r.intersectsNode(root)||r.isPointInRange(root,99))throw 'child versus main roots';
"#);}
#[test]
fn range_child_endpoint_origin_guard_conversion_reentry_and_content_producer_refusal(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var r=new mainCtor();r.selectNodeContents(html);var calls=0,beforeStart=r.startOffset,beforeEnd=r.endOffset,caught=0;for(var fn of [function(){r.cloneContents();},function(){r.extractContents();},function(){r.deleteContents();},function(){r.insertNode(document.createElement('span'));},function(){r.surroundContents(document.createElement('b'));}]){try{fn();}catch(e){if(e instanceof DOMException&&e.name==='NotSupportedError')caught++;}}if(caught!==5||r.startContainer!==html||r.startOffset!==beforeStart||r.endOffset!==beforeEnd||cd.body.firstChild!==null||root.textContent!=='Main')throw 'child content producer guard before any effects';
"#);let before=(p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end);p.set_location(&crate::navigation::address("https://foreign.test/source",&crate::navigation::Location::home()).unwrap());
 for source in ["r.startContainer","r.startOffset","r.commonAncestorContainer","r.cloneRange()","new mainCtor().compareBoundaryPoints({valueOf:function(){calls++;return 0;}},r)","r.setStart(root,{valueOf:function(){calls++;return 0;}})"]{let guarded=format!("try{{{source};throw 'missing endpoint authority refusal';}}catch(e){{if(!(e instanceof DOMException)||e.name!=='SecurityError'||e.message.indexOf('origin')<0)throw e;}}");run(&mut d,&mut f,&mut p,&guarded);assert_eq!((p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end),before);}
 p.set_location(&crate::navigation::address("https://child-range.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(calls||r.startContainer!==html||r.endOffset!==2)throw 'live endpoint origin refusal before conversion';r.setStart(body,0);if(r.startContainer!==body||r.endContainer!==html)throw 'fresh live child origin recovery';var failed=false;r.setStart(root,0);try{r.setEnd(body,{valueOf:function(){calls++;frame.parentNode.removeChild(frame);return 0;}});}catch(e){failed=true;}if(!failed||calls!==1||r.startContainer!==root||r.endContainer!==root||r.startOffset||r.endOffset)throw 'native child endpoint recheck after author conversion preserves completed removal and old Range';var fresh=document.createElement('iframe');fresh.hidden=true;document.body.appendChild(fresh);var next=fresh.contentDocument;r.setEnd(next.body,0);if(r.startContainer!==next.body||r.endContainer!==next.body||!r.collapsed)throw 'fresh child factory recovery after retained teardown refusal';");
}
#[test]
fn range_child_native_record_backing_refusal_has_no_identity_or_dom_prefix_and_recovers(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();p.begin_job();let Value::Host(window)=p.runtime.execute("w",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("native Window")};let Value::Host(document)=p.runtime.execute("cd",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("native Document")};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};bridge.create_range(window,document).unwrap();while bridge.state.ranges.len()<bridge.state.ranges.capacity(){bridge.create_range(window,document).unwrap();}let before=(bridge.state.retained,bridge.state.ranges.len(),bridge.state.ranges.capacity(),bridge.doc.nodes.len(),bridge.state.dom_commits);let limit=bridge.state.retained_limit;match profile{0=>bridge.state.host_work=0,1=>bridge.state.copy_work=0,2=>bridge.state.retained_limit=bridge.state.retained,_=>{bridge.state.host_work=4096;bridge.state.execution_deadline=Some(Instant::now());}}assert!(bridge.create_range(window,document).is_err());assert_eq!((bridge.state.retained,bridge.state.ranges.len(),bridge.state.ranges.capacity(),bridge.doc.nodes.len(),bridge.state.dom_commits),before);bridge.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var recovered=childFactory.call(cd);if(!(recovered instanceof childCtor)||recovered.startContainer!==cd||recovered.startOffset||!recovered.collapsed)throw 'native child Range backing fresh recovery';");}
}
